
import { apiResponse, createRequestContext } from "../../../lib/api";
import { SESSION_COOKIE_NAME } from "../../../lib/auth";
import { database } from "../../../lib/db";
import { DatabaseSessionStore } from "../../../lib/auth/database-session-store";
import { aiConfig, isAIConfigured } from "../../../lib/ai/config";
import { HttpAIProvider } from "../../../lib/ai/http-provider";
import { AIProviderError } from "../../../lib/ai/provider";

const sessionStore = new DatabaseSessionStore();

export async function POST(request: Request) {
  const context = createRequestContext(request);

    const cookieHeader = request.headers.get("cookie") ?? "";
      const token = cookieHeader
          .split(";")
              .map((part) => part.trim())
                  .find((part) => part.startsWith(`${SESSION_COOKIE_NAME}=`))
                      ?.slice(SESSION_COOKIE_NAME.length + 1);

                        if (!token) {
                            return apiResponse(
                                  {
                                          success: false,
                                                  error: {
                                                            code: "UNAUTHENTICATED",
                                                                      message: "Please log in to use Veloqis AI.",
                                                                              },
                                                                                    },
                                                                                          context,
                                                                                                401
                                                                                                    );
                                                                                                      }

                                                                                                        if (!database) {
                                                                                                            return apiResponse(
                                                                                                                  {
                                                                                                                          success: false,
                                                                                                                                  error: {
                                                                                                                                            code: "DATABASE_UNAVAILABLE",
                                                                                                                                                      message: "The service is temporarily unavailable.",
                                                                                                                                                              },
                                                                                                                                                                    },
                                                                                                                                                                          context,
                                                                                                                                                                                503
                                                                                                                                                                                    );
                                                                                                                                                                                      }

                                                                                                                                                                                        let body: unknown;

                                                                                                                                                                                          try {
                                                                                                                                                                                              body = await request.json();
                                                                                                                                                                                                } catch {
                                                                                                                                                                                                    return apiResponse(
                                                                                                                                                                                                          {
                                                                                                                                                                                                                  success: false,
                                                                                                                                                                                                                          error: {
                                                                                                                                                                                                                                    code: "INVALID_JSON",
                                                                                                                                                                                                                                              message: "Please send a valid JSON request.",
                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                  context,
                                                                                                                                                                                                                                                                        400
                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                if (
                                                                                                                                                                                                                                                                                    typeof body !== "object" ||
                                                                                                                                                                                                                                                                                        body === null ||
                                                                                                                                                                                                                                                                                            !("message" in body) ||
                                                                                                                                                                                                                                                                                                typeof body.message !== "string" ||
                                                                                                                                                                                                                                                                                                    !body.message.trim()
                                                                                                                                                                                                                                                                                                      ) {
                                                                                                                                                                                                                                                                                                          return apiResponse(
                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                        success: false,
                                                                                                                                                                                                                                                                                                                                error: {
                                                                                                                                                                                                                                                                                                                                          code: "INVALID_MESSAGE",
                                                                                                                                                                                                                                                                                                                                                    message: "Please provide a non-empty message.",
                                                                                                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                                                                                                        context,
                                                                                                                                                                                                                                                                                                                                                                              400
                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                      if (body.message.trim().length > 12000) {
                                                                                                                                                                                                                                                                                                                                                                                          return apiResponse(
                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                        success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                error: {
                                                                                                                                                                                                                                                                                                                                                                                                                          code: "INVALID_MESSAGE",
                                                                                                                                                                                                                                                                                                                                                                                                                                    message: "Message must contain at most 12000 characters.",
                                                                                                                                                                                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                                                                                                                                                                                        context,
                                                                                                                                                                                                                                                                                                                                                                                                                                                              400
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                      let session;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            session = await sessionStore.getByToken(decodeURIComponent(token));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return apiResponse(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        error: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  code: "SESSION_LOOKUP_FAILED",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            message: "Authentication is temporarily unavailable.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                context,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      503
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!session) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return apiResponse(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        error: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  code: "INVALID_SESSION",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            message: "Your session has expired. Please log in again.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                context,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      401
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const authenticatedContext = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ...context,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      userId: session.userId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          authenticated: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!isAIConfigured) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return apiResponse(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        error: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  code: "AI_MODEL_NOT_CONFIGURED",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            message: "The AI provider is not configured yet.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                authenticatedContext,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      503
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const provider = new HttpAIProvider(aiConfig);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const result = await provider.generate([
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    role: "system",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            content:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "You are Veloqis AI, an independent AI assistant. Be helpful, clear, and honest.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          role: "user",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  content: body.message.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return apiResponse(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              success: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      data: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                message: result.content,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          model: result.model,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              authenticatedContext,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    200
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const code =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    error instanceof AIProviderError
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? error.code
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : "AI_PROVIDER_ERROR";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return apiResponse(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              error: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        code,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  message:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "Veloqis AI could not get a response from the AI provider.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  authenticatedContext,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        502
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }